const inputItem = $input.first().json;
let rawText = inputItem.output || inputItem.text || "";

// Clean code blocks if present
rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

let parsed = {};
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  // Fallback in case JSON parsing fails
  parsed = {
    is_final_draft: false,
    chat_message: rawText,
    revision_summary: "",
    captions: {}
  };
}

const isFinal = parsed.is_final_draft ?? true;
const chatMessage = parsed.chat_message || "";
const summary = parsed.revision_summary || "";
const caps = parsed.captions || {};

// Format human-readable Slack text
let slackFormattedText = "";

if (!isFinal) {
  // If rejection/chat mode, output conversational prompt
  slackFormattedText = chatMessage || "Draft declined. Please let me know what changes you would like.";
} else {
  // If draft is ready (initial or revision), build structured output
  let summaryHeader = summary ? `*REVISION SUMMARY:*\n${summary}\n\n---\n\n` : "";

  slackFormattedText = `${summaryHeader}*CURRENT REVISED DRAFT DETAILS*\n` +
    `*Content Type:* ${caps.content_type || 'N/A'}\n\n` +
    `*Facebook:* ${caps.fb_caption || ''}\n\n` +
    `*Instagram:* ${caps.ig_caption || ''}\n\n` +
    `*Threads:* ${caps.threads_caption || ''}\n\n` +
    `*LinkedIn:* ${caps.linkedin_caption || ''}\n\n` +
    `*TikTok:* ${caps.tiktok_caption || ''}\n\n` +
    `*YouTube Title:* ${caps.yt_title || ''}\n\n` +
    `*YouTube Description:* ${caps.yt_description || ''}`;
}

return [{
  json: {
    is_final_draft: isFinal,
    chat_message: chatMessage,
    revision_summary: summary,
    slack_formatted_text: slackFormattedText,
    content_type: caps.content_type || "",
    fb_caption: caps.fb_caption || "",
    ig_caption: caps.ig_caption || "",
    threads_caption: caps.threads_caption || "",
    linkedin_caption: caps.linkedin_caption || "",
    tiktok_caption: caps.tiktok_caption || "",
    yt_title: caps.yt_title || "",
    yt_description: caps.yt_description || "",
    ...inputItem
  }
}];

const container = $('TikTok Container1').first().json.data;
const videoItem = $('Download file1').first();

if (!videoItem.binary || !videoItem.binary.data) {
  throw new Error('No binary "data" found on Download file node output.');
}

const binaryData = videoItem.binary.data;
let exactByteLength = 0;

// 1. Check if n8n provides exact fileSizeBytes property directly
if (binaryData.fileSizeBytes) {
  exactByteLength = parseInt(binaryData.fileSizeBytes, 10);
} 
// 2. Base64 memory mode (string must be long, not a short filesystem pointer)
else if (binaryData.data && binaryData.data.length > 1000) {
  const buffer = Buffer.from(binaryData.data, 'base64');
  exactByteLength = buffer.length;
} 
// 3. Filesystem / Disk mode (retrieve real buffer via n8n helper)
else {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data', 'Download file');
    exactByteLength = buffer.length;
  } catch (err) {
    // Fallback: estimate bytes if helper call is restricted
    const mb = parseFloat(binaryData.fileSize);
    exactByteLength = Math.round(mb * 1024 * 1024);
  }
}

if (!exactByteLength || exactByteLength < 100000) {
  throw new Error(`Byte length calculation failed: evaluated to ${exactByteLength} bytes.`);
}

return [{
  json: {
    upload_url: container.upload_url,
    publish_id: container.publish_id,
    exactByteLength: exactByteLength
  },
  binary: {
    data: binaryData
  }
}];

